// 「南楼熄灯以后」：两条调查路线在值班室汇合。所有标记只属于这一项任务。
function southChoice(text, next, result, effects = {}) {
  const { blood = 0, spirit = 0, favor = 0, flags = [], requiredFlag = '', requiredReason = '' } = effects;
  return { text, next, result, blood, spirit, favor, flags, requiredFlag, requiredReason, requiredSpirit: 0 };
}

function southChapter(title, paragraphs, choices) {
  return { title, text: paragraphs.join('\n\n'), choices, ending: false };
}

function southConclusion(title, paragraphs) {
  return { title, text: paragraphs.join('\n\n'), choices: [], ending: true };
}

export const SOUTH_CHAPTERS = [
  ['south_arrival'], ['south_register'], ['south_storage', 'south_gallery'],
  ['south_cabinet', 'south_window'], ['south_review'], ['south_owner'],
  ['south_transfer'], ['south_report'],
];

export const SOUTH_ENDINGS = ['south_ending_return', 'south_ending_revision', 'south_ending_hold'];

export function southEnding(state) {
  const has = flag => state.flags.includes(flag);
  const hasHandover = has('south_return_prepared') || has('south_evidence_prepared');
  if (hasHandover && has('south_redacted_report') && has('south_record') && has('south_consent') && state.spirit >= 35) {
    return 'south_ending_revision';
  }
  if ((hasHandover && has('south_private_report')) || (has('south_return_prepared') && has('south_redacted_report'))) {
    return 'south_ending_return';
  }
  return 'south_ending_hold';
}

